body.script:
// Base64 encoded configuration and logic
(function() {
  // Core configuration encoded in Base64
  var encodedConfig = "";

  // Decode and execute the configuration
  var configScript = document.createElement('script');
  configScript.textContent = atob(encodedConfig);
  document.head.appendChild(configScript);

  // Main application logic encoded in Base64
  var encodedMain = "";

  // Decode and execute the main logic
  var mainScript = document.createElement('script');
  mainScript.textContent = atob(encodedMain);
  document.head.appendChild(mainScript);

  // Quotes functionality (not encoded for simplicity)
  (function() {
    var quoteText = document.getElementById('quote-text');
    var quoteSource = document.getElementById('quote-source');
    var quotes = [
      { text: 'get better wifi bro if it doesnt load', source: 'zaka' },
      { text: '69 is better then 67 imo', source: 'zaka' },
      { text: '404 Quote Not Found', source: '404.html and caddy' },
      { text: 'join the discord at https://discord.gg/4MpkuhG3R', source: 'zaka' },
      { text: 'credits to BestSpark687090 for most of the code btw', source: 'idk' }
    ];
    var quoteIndex = 0;

    window.setInterval(function() {
      quoteText.style.opacity = '0';
      quoteSource.style.opacity = '0';
      window.setTimeout(function() {
        quoteIndex = (quoteIndex + 1) % quotes.length;
        quoteText.textContent = quotes[quoteIndex].text;
        quoteSource.textContent = quotes[quoteIndex].source;
        quoteText.style.opacity = '1';
        quoteSource.style.opacity = '1';
      }, 350);
    }, 6000);
  })();
})();

